"""Generate editable copy, original vector artwork and print-ready HTML. No dependencies."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];C=json.loads((R/'content.json').read_text())
def e(t):return html.escape(t)
def txt(x,y,t,size=24,color='#17334c',weight=400):return f'<text x="{x}" y="{y}" fill="{color}" font-size="{size}" font-weight="{weight}">{e(t)}</text>'
def box(x,y,w,h,fill='#fff',stroke='#d7e2ea',r=16):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{stroke}"/>'
b=box(0,0,1200,570,'#f1f5f8','none',0)+txt(38,50,'How JobSeam connects the work',32,weight=700)+txt(38,82,'Illustrative system overview. Not a live application screenshot.',18,'#536b7e')
b+=box(35,112,255,325)+txt(57,150,'BRING IT IN',20,'#668b35',700)
for i,(a,d) in enumerate([('Opportunities','Boards · company sites · email'),('Talent','Resume · ZIP · roster · direct'),('Connected sources','Email · WhatsApp, when enabled')]):
 y=190+i*85;b+=txt(57,y,a,22,weight=700)+txt(57,y+29,d,15,'#536b7e')
b+=box(325,112,550,325,'#17334c','#17334c')+txt(350,152,'THE SHARED WORKSPACE',20,'#b6d58a',700)
for i,(a,d) in enumerate([('People + opportunities','Profiles · requirements · matching'),('The next step','Applications · interviews · placements'),('The ongoing relationship','Employment · documents · authorization')]):
 y=194+i*85;b+=txt(350,y,a,25,'white',700)+txt(350,y+31,d,20,'#c6d8e5')
b+=box(910,112,255,325)+txt(932,150,'WORK TOGETHER',20,'#668b35',700)
for i,(a,d) in enumerate([('Recruiters + HR','Review, coordinate and record'),('Consultants','Confirm details and contribute'),('Administrators','Set access and configuration')]):
 y=190+i*85;b+=txt(932,y,a,21,weight=700)+txt(932,y+29,d,15,'#536b7e')
for x in [300,885]:b+=f'<path d="M{x} 267h15m-6-6 6 6-6 6" fill="none" stroke="#6d9237" stroke-width="3"/>'
b+=box(35,463,1130,65,'#e9f1df','#cbdab6')+txt(65,503,'Collect   →   Review   →   Match   →   Submit   →   Place   →   Manage',26,'#3f6024',700)
b+=txt(38,554,'A Quezaal Inc. product  •  jobseam.com  •  Feature availability depends on configuration.',16,'#536b7e')
svg='<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="570" viewBox="0 0 1200 570" role="img" aria-labelledby="title desc"><title id="title">How JobSeam connects the work</title><desc id="desc">Opportunities and talent enter a shared workspace for matching, applications, placements, employment, authorization and documents. Recruiters, consultants and administrators work through their permitted roles. Illustrative overview, not a live screenshot.</desc><g font-family="Arial,Helvetica,sans-serif">'+b+'</g></svg>'
(R/'assets/system-overview.svg').write_text(svg)
css='''*{box-sizing:border-box}body{margin:0;background:#e9eef2;color:#23374a;font-family:Arial,Helvetica,sans-serif}.sheet{width:210mm;min-height:297mm;margin:20px auto;background:#fff;padding:13mm 14mm 11mm;position:relative;break-after:page}.sheet:last-child{break-after:auto}.mast{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #7d9f45;padding-bottom:12px}.logo{font-size:31px;font-weight:800;letter-spacing:-1px;color:#17334c}.logo span{color:#6d9237}.tag{font-size:9px;font-weight:700;letter-spacing:1px;color:#587084;text-transform:uppercase}h1{font-size:29px;line-height:1.12;letter-spacing:-.7px;color:#17334c;margin:20px 0 10px}h2{font-size:14px;color:#17334c;margin:0 0 6px;line-height:1.25}p{font-size:11px;line-height:1.5;margin:0 0 10px}.intro{font-size:13px;line-height:1.55}.audience{font-size:10px;color:#587084}.system{width:100%;height:auto;display:block;margin:15px 0 6px}.caption{font-size:8px;color:#587084}.tiles{display:grid;grid-template-columns:1fr 1fr;gap:15px 24px;margin-top:20px}.tile{break-inside:avoid}.num{font-size:9px;font-weight:700;color:#6d9237;margin-bottom:5px}.tile p{font-size:11px;margin:0;line-height:1.5}.cta{background:#17334c;color:#fff;border-radius:8px;padding:14px 17px;margin:20px 0 12px;display:flex;align-items:center;justify-content:space-between;gap:15px}.cta strong{font-size:14px}.cta a{font-size:10px;color:#d6e8bf}.scope{font-size:8px;line-height:1.45;color:#587084;margin:0}.bottom{display:flex;justify-content:space-between;margin-top:12px;padding-top:9px;border-top:1px solid #d7e2ea;font-size:8px;color:#587084}a{color:#476f29;text-decoration:none}.one h1{font-size:24px;margin-top:15px}.one .intro{font-size:11px}.one .system{margin-top:11px}.one .tiles{margin-top:13px;gap:12px 22px}.one h2{font-size:12px}.one .tile p{font-size:10.2px;line-height:1.45}.one .cta{padding:11px 14px;margin-top:16px}.one .scope{font-size:7.7px}.two .system{margin:25px 0 8px}.benefits{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:25px 0}.benefit{min-width:0;border-top:3px solid #7d9f45;padding-top:13px}.benefit h2{font-size:16px}.benefit p{font-size:12px}.callout{padding:20px;background:#f0f5eb;border-radius:8px;margin:22px 0}.callout h2{font-size:20px}.callout p{font-size:13px;margin-bottom:0}.page-title{font-size:25px}.two .tiles{gap:20px 24px}.two .tile p{font-size:11.2px}.detail{color:#587084;margin-top:5px!important;font-size:10.4px!important}.two .scope{font-size:8px}.two .cta{margin-top:22px}@page{size:A4;margin:0}@media print{body{background:#fff}.sheet{margin:0}}@media screen and (max-width:800px){.sheet{width:auto;min-height:0;margin:0;padding:24px}.tiles,.benefits{grid-template-columns:1fr}.tile p,.one .tile p,.two .tile p,.detail{font-size:14px!important}.scope,.one .scope{font-size:11px}.cta{flex-wrap:wrap}.tag{font-size:8px}}
'''
(R/'assets/flyer.css').write_text(css)
def mast(label):return f'<header class="mast"><div class="logo">Job<span>Seam</span></div><div class="tag">{label}</div></header>'
def footer(n,total):return f'<footer class="bottom"><span>A Quezaal Inc. product · November 12, 2026</span><span>jobseam.com · {n} / {total}</span></footer>'
def cta():return f'<div class="cta"><strong>{e(C["cta"])}</strong><span><a href="{C["site"]}">jobseam.com</a><br><a href="mailto:{C["email"]}">{C["email"]}</a></span></div>'
def image():return '<img class="system" src="assets/system-overview.svg" alt="Illustrative system overview: talent and opportunities enter one workspace for matching, applications, placements and ongoing records. Staff, consultants and administrators participate through their permitted roles."><p class="caption">Illustrative system overview. Features depend on configuration. Not a live screenshot.</p>'
def tiles(detail=False):return '<div class="tiles">'+''.join(f'<section class="tile"><div class="num">{i:02}</div><h2>{e(v["title"])}</h2><p>{e(v["text"])}</p>'+(f'<p class="detail">{e(v["detail"])}</p>' if detail else '')+'</section>' for i,v in enumerate(C['capabilities'],1))+'</div>'
def doc(title,body):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+'</title><link rel="stylesheet" href="assets/flyer.css"></head><body>'+body+'</body></html>'
one='<article class="sheet one">'+mast('Product overview')+f'<h1>{e(C["headline"])}</h1><p class="intro">{e(C["intro"])}</p><p class="audience">{e(C["audience"])}</p>'+image()+tiles()+cta()+f'<p class="scope">{e(C["scope"])}</p>'+footer(1,1)+'</article>'
(R/'one-page.html').write_text(doc('JobSeam | One-page overview',one))
p1='<article class="sheet two">'+mast('The connected recruiting workspace')+f'<h1>{e(C["headline"])}</h1><p class="intro">{e(C["intro"])}</p>'+image()+'<div class="benefits">'+''.join('<section class="benefit"><h2>'+e(v['title'])+'</h2><p>'+e(v['text'])+'</p></section>' for v in C['benefits'])+'</div><section class="callout"><h2>From the first resume to the next assignment.</h2><p>'+e(C['audience'])+' Consultants have their own portal to review details and contribute updates.</p></section>'+cta()+footer(1,2)+'</article>'
p2='<article class="sheet two">'+mast('What your team can do')+'<h1 class="page-title">The work stays connected.</h1><p>One place to follow the person, the opportunity and the next step.</p>'+tiles(True)+cta()+f'<p class="scope">{e(C["scope"])}</p>'+footer(2,2)+'</article>'
(R/'two-page-flyer.html').write_text(doc('JobSeam | Two-page flyer',p1+p2))
base='# JobSeam\n\n**'+C['headline']+'**\n\n'+C['intro']+'\n\n'+C['audience']+'\n\n![How JobSeam connects talent, opportunities and ongoing work. Illustrative overview, not a live screenshot.](assets/system-overview.png)\n\n'
body=''.join('## '+v['title']+'\n\n'+v['text']+'\n\n' for v in C['capabilities'])
end='**'+C['cta']+'**\n\n[jobseam.com]('+C['site']+') · ['+C['email']+'](mailto:'+C['email']+')\n\n*'+C['scope']+'*\n'
(R/'one-page.md').write_text(base+body+end)
(R/'two-page-flyer.md').write_text(base+'## Page 1: The story\n\n'+''.join('### '+v['title']+'\n\n'+v['text']+'\n\n' for v in C['benefits'])+'## Page 2: The capabilities\n\n'+''.join('### '+v['title']+'\n\n'+v['text']+' '+v['detail']+'\n\n' for v in C['capabilities'])+end)
blogbase=base.replace('(assets/system-overview.png)', '(https://jobseam.com/collateral/product-overview/assets/system-overview.png)')
blogdownloads='## Take a closer look\n\n[Download the one-page overview](https://jobseam.com/collateral/product-overview/one-page.pdf) or [read the two-page flyer](https://jobseam.com/collateral/product-overview/two-page-flyer.pdf).\n\n'
(R/'blog-ready.md').write_text(blogbase+body+blogdownloads+end)
print('Generated two flyers, blog copy and original system artwork.')
